(()=>{'use strict';
const C=window.HEFESTO_CATALOG,E=window.HefestoEngine,$=s=>document.querySelector(s),esc=E.esc;
const state={category:'Todos los rubros',limit:12,favorites:false,compare:new Set(),selected:null,system:'web'};
let saved=new Set();try{saved=new Set(JSON.parse(localStorage.getItem('hefesto-favorites')||'[]').filter(id=>C.packs.some(p=>p.id===id)));}catch{}
const normalize=v=>v.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();
let timer;function toast(s){$('#toast').textContent=s;$('#toast').classList.add('visible');clearTimeout(timer);timer=setTimeout(()=>$('#toast').classList.remove('visible'),3000);}
function thumbnail(p,style){return `<div class="thumb live-thumb" data-family="${esc(p.design.family)}"><iframe class="thumb-frame" src="thumbs/${p.id}-${style}.html?v=4.1.0" loading="lazy" tabindex="-1" aria-hidden="true" title="Diseño ${esc(p.name)}" sandbox="allow-same-origin"></iframe><span class="thumb-hover">Explorar experiencia ↗</span></div>`;}
const sizeThumbs=new ResizeObserver(entries=>entries.forEach(({target,contentRect})=>target.style.setProperty('--thumb-scale',contentRect.width/1440)));
const observedThumbs=new Set();function observeThumbs(){for(const t of observedThumbs)if(!t.isConnected){sizeThumbs.unobserve(t);observedThumbs.delete(t);}document.querySelectorAll('.live-thumb').forEach(t=>{if(!observedThumbs.has(t)){sizeThumbs.observe(t);observedThumbs.add(t);}});}

function render(append=false){append=append===true;const q=normalize($('#search').value);const filtered=C.packs.filter(p=>(state.category==='Todos los rubros'||p.category===state.category)&&(!state.favorites||saved.has(p.id))&&normalize([p.name,p.category,...p.categories,...p.tags,...p.items.map(i=>i.name)].join(' ')).includes(q));
$('#categories').innerHTML=['Todos los rubros',...new Set(C.packs.map(p=>p.category))].map(c=>`<button data-category="${esc(c)}" class="${state.category===c?'active':''}" aria-pressed="${state.category===c}"><span>${esc(c)}</span><b>${c==='Todos los rubros'?48:C.packs.filter(p=>p.category===c).length}</b></button>`).join('');
$('#category-title').textContent=state.favorites?'Tus plantillas guardadas':state.category;$('#result-count').textContent=`${filtered.length} packs · ${C.plans[$('#plan').value].label} · ${$('#style-filter').selectedOptions[0].text}`;
const start=append?$('#catalogue').children.length:0;const cards=filtered.slice(start,state.limit).map(p=>`<article class="template-card"><button class="thumb-button" data-open="${p.id}" aria-label="Previsualizar ${esc(p.name)}">${thumbnail(p,$('#style-filter').value)}${p.featured?'<span class="badge">DISEÑO DE AUTOR</span>':''}</button><div class="card-copy"><span class="card-category">${esc(window.HefestoDesign.families[p.design.family])}</span><div class="card-title"><h3>${esc(p.name)}</h3><button class="save-button" data-save="${p.id}" aria-label="Guardar ${esc(p.name)}" aria-pressed="${saved.has(p.id)}">${saved.has(p.id)?'♥':'♡'}</button></div><div class="systems"><span>GSAP</span>${p.design.threejs?'<span class="tech-tag">Three.js · 3D</span>':'<span>Dirección editorial</span>'}<span>Sitio + tienda</span><span>Gestión</span>${$('#plan').value!=='basico'?'<span>Atención</span>':''}${$('#plan').value==='premium'?'<span>Documentos</span>':''}</div><div class="card-actions"><button data-open="${p.id}">Explorar plantilla ↗</button><label><input type="checkbox" data-compare="${p.id}" ${state.compare.has(p.id)?'checked':''}> Comparar</label></div></div></article>`).join('');
if(append)$('#catalogue').insertAdjacentHTML('beforeend',cards);else $('#catalogue').innerHTML=cards;
$('#empty').hidden=filtered.length>0;$('#load-more').hidden=state.limit>=filtered.length;$('#fav-count').textContent=saved.size;$('#favorites').setAttribute('aria-pressed',state.favorites);$('#compare-tray').hidden=!state.compare.size;$('#compare-count').textContent=`${state.compare.size} de 3 plantillas`;observeThumbs();
}
let previewSequence=0,previewRequest='',previewTimer;
function previewState(status,message=''){
 const panel=$('#preview-state');panel.hidden=status==='ready';panel.dataset.state=status;
 $('#preview-status').textContent=message||(status==='error'?'No se pudo cargar la vista previa.':'Preparando el diseño…');
 $('#preview-retry').hidden=status!=='error';$('#preview').setAttribute('aria-busy',String(status==='loading'));
}
function loadPreview(){
 if(!state.selected)return;
 clearTimeout(previewTimer);previewRequest=String(++previewSequence);previewState('loading');
 const url=new URL('demo.html',document.baseURI);url.search=new URLSearchParams({pack:state.selected.id,style:$('#detail-style').value,system:state.system,...settings(),request:previewRequest,v:C.design_version});
 $('#preview').src=url.href;
 previewTimer=setTimeout(()=>previewState('error','La vista está tardando en cargar. Puedes reintentar sin cambiar de pestaña.'),15000);
}
window.addEventListener('message',event=>{
 if(event.source!==$('#preview').contentWindow||event.origin!==location.origin||event.data?.type!=='hefesto-preview'||event.data.request!==previewRequest)return;
 if(!['ready','error'].includes(event.data.status))return;
 clearTimeout(previewTimer);previewState(event.data.status,event.data.message);
});
$('#preview-retry').onclick=loadPreview;
const settings=()=>({name:$('#business-name').value,headline:$('#headline').value,primary:$('#accent').value});
function updatePreview(){if(!state.selected)return;const p=state.selected,plan=$('#detail-plan').value;const allowed=['web','gestion',...(plan!=='basico'?['atencion']:[]),...(plan==='premium'?['documentos']:[])];if(!allowed.includes(state.system))state.system='web';const labels={web:'Sitio + tienda',gestion:'Odoo · gestión',atencion:'Chatwoot · atención',documentos:'InvoiceNinja · documentos'};
$('#system-tabs').innerHTML=Object.entries(labels).map(([id,label])=>`<button data-system="${id}" aria-pressed="${state.system===id}" ${allowed.includes(id)?'':'disabled'}>${label}</button>`).join('');loadPreview();$('#color-value').textContent=$('#accent').value;$('#demo-open').href='demo.html?'+new URLSearchParams({pack:p.id,style:$('#detail-style').value,...settings()});
$('#preview-caption').textContent=state.system==='web'?window.HefestoDesign.families[p.design.family]+' · Tailwind + GSAP'+(p.design.threejs?' + Three.js':'')+' · ejemplo interactivo':'Maqueta del pack · no es una instancia activa del sistema';
const sel=E.selection(C,p,settings(),plan,$('#detail-style').value);$('#included').innerHTML=`<b>Incluido en ${esc(C.plans[plan].label)}</b><p>${Object.keys(sel.systems).map(esc).join(' · ')}</p><p>POS: ${sel.pos_enabled?'propuesto para este pack':'no incluido en esta selección'}</p>`;
$('#pack-details').innerHTML=`<p><b>Categorías:</b> ${p.categories.map(esc).join(', ')}.</p><p><b>Proceso comercial:</b> ${p.stages.map(esc).join(' → ')}.</p><p>${p.requirements.map(esc).join(' ')}</p><p>Los CSV y patrones son bases editables. La conexión con cada sistema, los permisos y la reversión requieren implementación y pruebas.</p>`;
}
function resetBrand(){const p=state.selected;$('#business-name').value=p.brand.name;$('#headline').value=p.brand.headline;$('#accent').value=p.brand.primary;updatePreview();}
function open(id){state.selected=C.packs.find(p=>p.id===id);if(!state.selected)return;const p=state.selected;$('#detail-name').textContent=p.name;$('#detail-category').textContent=p.category;$('#detail-style').value=$('#style-filter').value;$('#detail-plan').value=$('#plan').value;$('#pack-download').href=`downloads/${p.id}.zip`;state.system='web';$('#detail').classList.remove('is-editing');$('#customize-toggle').setAttribute('aria-expanded','false');$('#detail').showModal();resetBrand();}
function download(name,content,type){const url=URL.createObjectURL(new Blob([content],{type})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Archivo preparado para descargar.');}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.category){state.category=b.dataset.category;state.limit=12;render();}if(b.dataset.open){if($('#compare-dialog').open)$('#compare-dialog').close();open(b.dataset.open);}if(b.dataset.save){const id=b.dataset.save;saved.has(id)?saved.delete(id):saved.add(id);try{localStorage.setItem('hefesto-favorites',JSON.stringify([...saved]));}catch{}render();}if(b.dataset.close)$('#'+b.dataset.close).close();if(b.dataset.system){state.system=b.dataset.system;updatePreview();}if(b.dataset.device){$('#frame-wrap').classList.toggle('mobile',b.dataset.device==='mobile');document.querySelectorAll('[data-device]').forEach(x=>x.setAttribute('aria-pressed',x===b));}});
document.addEventListener('change',e=>{const id=e.target.dataset.compare;if(!id)return;if(e.target.checked){if(state.compare.size>=3){e.target.checked=false;toast('Puedes comparar hasta tres packs.');return;}state.compare.add(id);}else state.compare.delete(id);render();});
$('#search').addEventListener('input',()=>{state.limit=12;render();});['plan','style-filter'].forEach(id=>$('#'+id).addEventListener('change',render));$('#favorites').onclick=()=>{state.favorites=!state.favorites;state.limit=12;render();};$('#load-more').onclick=()=>{state.limit+=12;render(true);};$('#reset').onclick=()=>{state.category='Todos los rubros';state.limit=12;state.favorites=false;$('#search').value='';$('#plan').value='premium';$('#style-filter').value='editorial';render();};$('#compare-clear').onclick=()=>{state.compare.clear();render();};
$('#compare-open').onclick=()=>{if(state.compare.size<2){toast('Selecciona al menos dos packs.');return;}$('#compare-content').innerHTML=[...state.compare].map(id=>{const p=C.packs.find(x=>x.id===id);return `<article>${thumbnail(p,$('#style-filter').value)}<h3>${esc(p.name)}</h3><p>${esc(p.category)}</p><b>Catálogo inicial</b><p>${p.categories.map(esc).join(' · ')}</p><b>Proceso comercial</b><p>${p.stages.map(esc).join(' → ')}</p><button class="dark-button" data-open="${p.id}">Personalizar este pack</button></article>`;}).join('');$('#compare-dialog').showModal();observeThumbs();};
$('#detail').addEventListener('close',()=>{clearTimeout(previewTimer);clearTimeout(debounce);previewRequest='';$('#preview').src='about:blank';});
$('#customize-toggle').onclick=()=>{const expanded=$('#detail').classList.toggle('is-editing');$('#customize-toggle').setAttribute('aria-expanded',String(expanded));};
$('#guide-open').onclick=()=>$('#guide').showModal();let debounce;['business-name','headline','accent'].forEach(id=>$('#'+id).addEventListener('input',()=>{clearTimeout(debounce);debounce=setTimeout(updatePreview,300);}));['detail-style','detail-plan'].forEach(id=>$('#'+id).onchange=updatePreview);$('#brand-reset').onclick=resetBrand;
$('#selection-download').onclick=()=>download(`${state.selected.id}-seleccion.json`,JSON.stringify(E.selection(C,state.selected,settings(),$('#detail-plan').value,$('#detail-style').value),null,2),'application/json');$('#html-download').onclick=async()=>{const button=$('#html-download');button.disabled=true;button.textContent='Preparando HTML…';try{const html=E.render(state.selected,settings(),$('#detail-style').value,state.system);const doc=new DOMParser().parseFromString(html,'text/html');const read=async url=>{const res=await fetch(url);if(!res.ok)throw Error('Recurso no disponible');return res;};await Promise.all([...doc.querySelectorAll('script[src],link[rel=stylesheet],img[src]')].map(async node=>{const url=node.getAttribute('src')||node.getAttribute('href'),res=await read(url);if(node.tagName==='IMG'){const blob=await res.blob();const data=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=reject;reader.readAsDataURL(blob);});node.setAttribute('src',data);}else if(node.tagName==='SCRIPT'){node.removeAttribute('src');node.textContent=(await res.text()).replace(/<\/script/gi,'<\\/script');}else{const style=doc.createElement('style');style.textContent=await res.text();node.replaceWith(style);}}));download(`${state.selected.id}-${state.system}.html`,'<!doctype html>'+doc.documentElement.outerHTML,'text/html');}catch{toast('No se completó la descarga. Prueba el ZIP del pack.');}finally{button.disabled=false;button.textContent='Descargar HTML autónomo';}};
let theme='system';try{theme=localStorage.getItem('hefesto-theme')||'system';}catch{}const media=matchMedia('(prefers-color-scheme: dark)');function applyTheme(){document.documentElement.dataset.theme=theme==='system'?(media.matches?'dark':'light'):theme;$('#theme').textContent='Tema: '+({system:'sistema',light:'claro',dark:'oscuro'}[theme]);}$('#theme').onclick=()=>{theme=['system','light','dark'][(['system','light','dark'].indexOf(theme)+1)%3];try{localStorage.setItem('hefesto-theme',theme);}catch{}applyTheme();};media.addEventListener('change',applyTheme);applyTheme();render();
})();
